mapper.select:
SELECT * FROM ( SELECT leave_id as todo_id, 'leave' as todo_type, leave_type as todo_title, leave_reason as todo_content, user_name as apply_user, apply_time, CASE WHEN approval_status = '1' THEN '0' ELSE '1' END as status, leave_id as related_id FROM oa_leave WHERE user_id = #{userId} AND del_flag = '0' UNION ALL SELECT reimb_id, 'reimbursement', reimb_type, reimb_reason, user_name, apply_time, CASE WHEN approval_status = '1' THEN '0' ELSE '1' END, reimb_id FROM oa_reimbursement WHERE user_id = #{userId} AND del_flag = '0' ) t
AND todo_title LIKE #{todoTitleLike}
AND status = #{status}
ORDER BY apply_time DESC
